DRAFTS_CONTACT_POLICY_FN = """
CREATE FUNCTION drafts_enforce_contact_policy() RETURNS trigger AS $$
DECLARE
    policy text;
BEGIN
    IF NEW.kind = 'outreach_email' AND NEW.status <> 'discarded' THEN
        SELECT c.contact_policy INTO policy
        FROM jobs j LEFT JOIN companies c ON c.id = j.company_id
        WHERE j.id = NEW.job_id;
        IF policy IS DISTINCT FROM 'allowed' THEN
            RAISE EXCEPTION 'outreach drafts are not allowed for job %: contact policy is %',
                NEW.job_id, COALESCE(policy, 'unknown (no company)')
                USING ERRCODE = 'check_violation', CONSTRAINT = 'drafts_contact_policy';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql
"""

COMPANIES_POLICY_CHANGE_FN = """
CREATE FUNCTION companies_discard_outreach_drafts() RETURNS trigger AS $$
BEGIN
    UPDATE drafts SET status = 'discarded', updated_at = now()
    WHERE kind = 'outreach_email'
      AND status <> 'discarded'
      AND job_id IN (SELECT id FROM jobs WHERE company_id = NEW.id);
    RETURN NULL;
END;
$$ LANGUAGE plpgsql
"""


